package com.greenocean.backend.catalog.service;

import com.greenocean.backend.common.exception.*;
import com.greenocean.backend.identity.AccessPolicy;
import com.greenocean.backend.auth.service.AuthRateLimit;
import com.greenocean.backend.post.service.PostService;
import com.greenocean.backend.wellbeing.service.PrivateWellbeing;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import tools.jackson.databind.ObjectMapper;
import java.net.URI;
import java.time.*;
import java.util.*;

@Service @Transactional
public class GrowthLibrary {
 private final JdbcTemplate db;private final AccessPolicy access;private final AuthRateLimit rates;private final PostService posts;private final ObjectMapper json;private final boolean publication;
 public GrowthLibrary(JdbcTemplate db,AccessPolicy access,AuthRateLimit rates,PostService posts,ObjectMapper json,@Value("${greenocean.education.publication-approved:false}")boolean publication){this.db=db;this.access=access;this.rates=rates;this.posts=posts;this.json=json;this.publication=publication;}
 public record Draft(Map<String,Object> document,int revision,long etag){}
 public record Decision(int revision,long etag,String decision,String note,boolean sourcesChecked,boolean rightsChecked){}
 public record Grant(UUID userId,String action,String scope,String evidence,Instant expiresAt){}
 public record Credential(UUID userId,UUID verificationId,String scope,String reference,Instant expiresAt){}
 public record Preference(boolean allowed,long revision){}
 public record Proposal(UUID resourceId,String reason){}
 private String text(Object value,int max,boolean required){if(value!=null&&!(value instanceof String))throw new IllegalArgumentException("Expected text metadata");return PrivateWellbeing.text((String)value,max,required);}
 public void actor(UUID user){if(db.queryForList("SELECT id FROM users WHERE id=? AND status='ACTIVE' FOR SHARE",UUID.class,user).isEmpty())throw new ForbiddenException("The account is unavailable");access.require(user,"COMMUNITY");if(!Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM account_eligibility WHERE user_id=? AND age_result='ADULT')",Boolean.class,user)))throw new ForbiddenException("Adult eligibility is required");if(!rates.allowInCurrentTransaction("growth-library:"+user,600,Duration.ofHours(1)))throw new com.greenocean.backend.listener.live.LiveSupportException(429,"RATE_LIMITED","Please pause before trying again.");}
 private boolean truth(String sql,Object...args){return Boolean.TRUE.equals(db.queryForObject(sql,Boolean.class,args));}
 public void staff(UUID user){if(!truth("SELECT EXISTS(SELECT 1 FROM users u JOIN user_roles ur ON ur.user_id=u.id JOIN roles r ON r.id=ur.role_id WHERE u.id=? AND u.status='ACTIVE' AND r.name IN('ADMIN','MODERATOR'))",user))throw new ForbiddenException("Current staff authority is required");}
 public void admin(UUID user){staff(user);if(!truth("SELECT EXISTS(SELECT 1 FROM user_roles ur JOIN roles r ON r.id=ur.role_id WHERE ur.user_id=? AND r.name='ADMIN')",user))throw new ForbiddenException("Current administrative authority is required");}
 public void permission(UUID user,String action,String scope){actor(user);if(!truth("SELECT educational_permission_live(?,?,?)",user,action,scope))throw new ForbiddenException("A current explicit educational-content permission is required");if(!scope.equals("GENERAL")&&!truth("SELECT educational_credential_live(?,?)",user,scope))throw new ForbiddenException("Current independently verified contribution scope is required");}
 public static String external(String value){if(value==null||value.isBlank())return "";try{String raw=value.trim();URI uri=URI.create(raw);String host=uri.getHost();if(host!=null)host=host.toLowerCase(Locale.ROOT).replaceAll("\\.$","");String decoded=java.net.URLDecoder.decode(raw,java.nio.charset.StandardCharsets.UTF_8);if(!"https".equalsIgnoreCase(uri.getScheme())||host==null||uri.getUserInfo()!=null||uri.getPort()!=-1&&uri.getPort()!=443||decoded.chars().anyMatch(c->c<32||c==127)||host.equalsIgnoreCase("localhost")||host.endsWith(".local")||host.endsWith(".localhost")||!host.contains(".")||host.matches("[0-9.]+")||host.contains(":"))throw new IllegalArgumentException();return uri.toASCIIString();}catch(RuntimeException error){throw new IllegalArgumentException("Use a public HTTPS source without credentials or control characters");}}
 private Map<String,Object> validated(Map<String,Object> doc,boolean submitted){if(doc==null||doc.size()>25||json.writeValueAsString(doc).length()>100000)throw new IllegalArgumentException("Resource metadata is required");var result=new LinkedHashMap<String,Object>();Set<String> allowed=Set.of("kind","title","summary","body","creator","year","language","topic","why","audience","warnings","sources","externalUrl","rights","scope","objectives","modules");if(!allowed.containsAll(doc.keySet()))throw new IllegalArgumentException("Unknown resource field");String kind=text(doc.get("kind"),30,true);if(!Set.of("BOOK","FILM","SERIES","DOCUMENTARY","MUSIC","ARTICLE","NOTE","GUIDE","TEMPLATE","COURSE").contains(kind))throw new IllegalArgumentException("Unsupported resource type");result.put("kind",kind);for(String field:List.of("title","summary","body","creator","language","topic","why","audience","rights","scope","objectives")){int max=field.equals("body")?50000:field.equals("summary")?600:field.equals("title")?220:field.equals("scope")||field.equals("topic")?80:field.equals("objectives")?3000:500;boolean required=Set.of("title","language","scope").contains(field)||submitted&&Set.of("summary","topic","why","audience","rights").contains(field);result.put(field,text(doc.get(field),max,required));}if(!Set.of("en","fa").contains(result.get("language")))throw new IllegalArgumentException("Unsupported resource language");if(!"ADULT".equals(result.get("audience"))&&submitted)throw new IllegalArgumentException("Initial educational content serves eligible adults");for(String field:List.of("warnings","sources")){Object raw=doc.get(field);if(raw!=null&&!(raw instanceof List<?>))throw new IllegalArgumentException("Expected a list");var list=raw==null?List.of():(List<?>)raw;if(list.size()>12)throw new IllegalArgumentException("Too many metadata items");var values=list.stream().map(x->text(x,1000,true)).map(x->field.equals("sources")?external(x):x).toList();if(submitted&&field.equals("sources")&&values.isEmpty())throw new IllegalArgumentException("Published references are required");result.put(field,values);}result.put("externalUrl",external(text(doc.get("externalUrl"),2000,false)));if(doc.get("year")!=null){if(!(doc.get("year") instanceof Number year)||year.intValue()<1000||year.intValue()>2200)throw new IllegalArgumentException("Invalid publication year");result.put("year",((Number)doc.get("year")).intValue());}if(submitted&&Set.of("ARTICLE","NOTE","GUIDE","TEMPLATE").contains(kind)&&((String)result.get("body")).length()<40)throw new IllegalArgumentException("Genuine educational text is required");if(submitted&&Set.of("BOOK","FILM","SERIES","DOCUMENTARY","MUSIC").contains(kind)&&(((String)result.get("externalUrl")).isBlank()||((String)result.get("creator")).isBlank()))throw new IllegalArgumentException("Creator and legitimate external availability reference are required");if(kind.equals("COURSE")){if(((String)result.get("title")).length()>160)throw new IllegalArgumentException("Course title must fit 160 characters");result.put("modules",Curriculum.validate(doc.get("modules"),submitted));}else if(doc.containsKey("modules"))throw new IllegalArgumentException("Only a curriculum can contain lessons");return result;}
 private Map<String,Object> version(UUID id,int revision){var rows=db.queryForList("SELECT v.*,r.author_id,r.current_revision,r.published_revision,r.retired,r.featured,r.legacy_article_id,r.legacy_media_id FROM growth_resources r JOIN growth_resource_versions v ON v.resource_id=r.id WHERE r.id=? AND v.revision=?",id,revision);if(rows.isEmpty())throw new NotFoundException("Educational resource was not found");var row=rows.getFirst();row.put("document",json.readValue(row.get("document").toString(),Map.class));return row;}
 private Map<String,Object> locked(UUID id,int revision,long etag){var rows=db.queryForList("SELECT current_revision FROM growth_resources WHERE id=? FOR UPDATE",id);if(rows.isEmpty())throw new NotFoundException("Educational resource was not found");if(((Number)rows.getFirst().get("current_revision")).intValue()!=revision)throw new ConflictException("The content revision changed. Reload before acting.");var row=version(id,revision);if(((Number)row.get("etag")).longValue()!=etag)throw new ConflictException("The content changed. Reload before acting.");return row;}
 private String scope(Map<String,Object> row){return (String)((Map<?,?>)row.get("document")).get("scope");}
 private void event(UUID actor,UUID id,int revision,String action,String note){db.update("INSERT INTO growth_editorial_events(resource_id,revision,actor_id,action,note) VALUES (?,?,?,?,?)",id,revision,actor,action,text(note,3000,true));}
 public void requirePublication(){if(!publication)throw new ForbiddenException("Production educational publication is awaiting operational approval");}
 public Map<String,Object> create(UUID actor,Draft in){var doc=validated(in.document(),false);permission(actor,"DRAFT",(String)doc.get("scope"));UUID id=db.queryForObject("INSERT INTO growth_resources(author_id) VALUES (?) RETURNING id",UUID.class,actor);if("COURSE".equals(doc.get("kind")))doc.put("modules",Curriculum.identify(db,id,doc.get("modules")));db.update("INSERT INTO growth_resource_versions(resource_id,revision,document) VALUES (?,1,?::jsonb)",id,json.writeValueAsString(doc));event(actor,id,1,"DRAFT_CREATED","Author-created educational draft; not approved");return version(id,1);}
 public Map<String,Object> edit(UUID actor,UUID id,Draft in,boolean fork){actor(actor);var row=locked(id,in.revision(),in.etag());if(!actor.equals(row.get("author_id")))throw new NotFoundException("Own educational draft was not found");var doc=validated(in.document(),false);if(!Objects.equals(((Map<?,?>)row.get("document")).get("kind"),doc.get("kind")))throw new IllegalArgumentException("Create a separate resource when changing educational resource type");if(!Objects.equals(scope(row),doc.get("scope")))throw new IllegalArgumentException("Contribution scope cannot be changed on an existing resource");permission(actor,"DRAFT",scope(row));if("COURSE".equals(doc.get("kind")))doc.put("modules",Curriculum.identify(db,id,doc.get("modules")));int revision=in.revision();if(fork){revision++;db.update("INSERT INTO growth_resource_versions(resource_id,revision,document) VALUES (?,?,?::jsonb)",id,revision,json.writeValueAsString(doc));db.update("UPDATE growth_resources SET current_revision=? WHERE id=?",revision,id);}else{if(!row.get("state").equals("DRAFT"))throw new ConflictException("Create a new revision before changing submitted or reviewed content");db.update("UPDATE growth_resource_versions SET document=?::jsonb,etag=etag+1 WHERE resource_id=? AND revision=?",json.writeValueAsString(doc),id,revision);}event(actor,id,revision,fork?"REVISION_CREATED":"DRAFT_EDITED","Explicit author edit");return version(id,revision);}
 public Map<String,Object> transition(UUID actor,UUID id,Decision in){actor(actor);var row=locked(id,in.revision(),in.etag());String scope=scope(row),next=in.decision();if(!Set.of("SUBMIT","NEEDS_REVISION","APPROVE","REJECT","PUBLISH","RETIRE","FEATURE","UNFEATURE").contains(next))throw new IllegalArgumentException("Unknown editorial action");String note=text(in.note(),3000,true);if(next.equals("SUBMIT")){permission(actor,"SUBMIT",scope);if(!actor.equals(row.get("author_id"))||!row.get("state").equals("DRAFT"))throw new ConflictException("Only the author can submit the current draft");validated((Map<String,Object>)row.get("document"),true);db.update("UPDATE growth_resource_versions SET state='SUBMITTED',etag=etag+1 WHERE resource_id=? AND revision=?",id,in.revision());}else if(Set.of("APPROVE","NEEDS_REVISION","REJECT").contains(next)){staff(actor);permission(actor,"REVIEW",scope);if(actor.equals(row.get("author_id")))throw new ForbiddenException("Independent review is required");if(!row.get("state").equals("SUBMITTED"))throw new ConflictException("Only the submitted exact revision can be reviewed");if(next.equals("APPROVE")){permission(actor,"APPROVE",scope);permission((UUID)row.get("author_id"),"SUBMIT",scope);if(!in.sourcesChecked()||!in.rightsChecked())throw new IllegalArgumentException("Actual source and rights checks must be recorded");}db.update("UPDATE growth_resource_versions SET state=?,reviewer_id=?,review_note=?,reviewed_at=CURRENT_TIMESTAMP,sources_checked=?,rights_checked=?,etag=etag+1 WHERE resource_id=? AND revision=?",next.equals("APPROVE")?"APPROVED":next.equals("REJECT")?"REJECTED":"NEEDS_REVISION",actor,note,in.sourcesChecked(),in.rightsChecked(),id,in.revision());}else if(next.equals("PUBLISH")){staff(actor);permission(actor,"PUBLISH",scope);requirePublication();if(!row.get("state").equals("APPROVED"))throw new ConflictException("The exact revision needs independent approval");permission((UUID)row.get("author_id"),"SUBMIT",scope);permission((UUID)row.get("reviewer_id"),"REVIEW",scope);permission((UUID)row.get("reviewer_id"),"APPROVE",scope);db.update("UPDATE growth_resource_versions SET state='PUBLISHED',published_by=?,published_at=CURRENT_TIMESTAMP,etag=etag+1 WHERE resource_id=? AND revision=?",actor,id,in.revision());db.update("UPDATE growth_resources SET published_revision=?,retired=FALSE WHERE id=?",in.revision(),id);syncLegacy(id,in.revision());}else if(next.equals("RETIRE")){staff(actor);permission(actor,"RETIRE",scope);db.update("UPDATE growth_resources SET retired=TRUE,featured=FALSE WHERE id=?",id);db.update("UPDATE growth_resource_versions SET etag=etag+1 WHERE resource_id=? AND revision=?",id,in.revision());}else{staff(actor);permission(actor,"FEATURE",scope);if(!truth("SELECT growth_resource_available(?)",id))throw new ConflictException("Only an available reviewed publication may be featured");db.update("UPDATE growth_resources SET featured=? WHERE id=?",next.equals("FEATURE"),id);db.update("UPDATE growth_resource_versions SET etag=etag+1 WHERE resource_id=? AND revision=?",id,in.revision());}event(actor,id,in.revision(),next,note);return version(id,in.revision());}
 private void syncLegacy(UUID id,int revision){var row=version(id,revision);var d=(Map<String,Object>)row.get("document");if("COURSE".equals(d.get("kind")))publishCourse(id,revision,d,row);if(row.get("legacy_article_id")!=null)db.update("UPDATE professional_articles SET title=?,summary=?,topic=?,status='PUBLISHED',published_at=CURRENT_TIMESTAMP,evidence_level='General education; exact editorial revision reviewed',sections=?::jsonb,reference_list=?::jsonb WHERE id=?",d.get("title"),d.get("summary"),d.get("topic"),json.writeValueAsString(List.of(Map.of("heading",d.get("title"),"body",d.get("body")))),json.writeValueAsString(d.get("sources")),row.get("legacy_article_id"));if(row.get("legacy_media_id")!=null)db.update("UPDATE media_recommendations SET title=?,theme=?,description=?,discussion_prompt=?,content_notes=?,recommended_by=?,is_published=TRUE WHERE id=?",d.get("title"),d.get("topic"),d.get("summary"),((String)d.get("body")).substring(0,Math.min(500,((String)d.get("body")).length())),((List<String>)d.get("warnings")).toArray(String[]::new),db.queryForObject("SELECT display_name FROM profiles WHERE user_id=?",String.class,row.get("author_id")),row.get("legacy_media_id"));}
 private void publishCourse(UUID id,int revision,Map<String,Object> doc,Map<String,Object> row){var counts=db.queryForMap("SELECT count(*) AS count,COALESCE(sum(minutes),0) AS minutes FROM learning_lessons(?,?)",id,revision);if(((Number)counts.get("count")).intValue()==0)throw new ConflictException("A published course requires actual lessons");String author=db.queryForObject("SELECT display_name FROM profiles WHERE user_id=?",String.class,row.get("author_id"));db.update("INSERT INTO guided_growth_paths(id,resource_id,slug,title,summary,lesson_count,duration_minutes,author_name,evidence_note,reference_list,reviewed_at,is_published) VALUES (?,?,?,?,?,?,?,?,?,?,CURRENT_DATE,TRUE) ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,summary=EXCLUDED.summary,lesson_count=EXCLUDED.lesson_count,duration_minutes=EXCLUDED.duration_minutes,author_name=EXCLUDED.author_name,evidence_note=EXCLUDED.evidence_note,reference_list=EXCLUDED.reference_list,reviewed_at=EXCLUDED.reviewed_at,is_published=TRUE",id,id,"course-"+id,doc.get("title"),doc.get("summary"),counts.get("count"),counts.get("minutes"),author.substring(0,Math.min(120,author.length())),"General education; exact curriculum revision independently reviewed",((List<String>)doc.get("sources")).toArray(String[]::new));}
 public Map<String,Object> editorial(UUID actor,UUID id){actor(actor);var list=db.queryForList("SELECT current_revision FROM growth_resources WHERE id=?",Integer.class,id);if(list.isEmpty())throw new NotFoundException("Resource was not found");var row=version(id,list.getFirst());if(!actor.equals(row.get("author_id"))){staff(actor);permission(actor,"REVIEW",scope(row));}row.put("events",db.queryForList("SELECT revision,action,note,created_at FROM growth_editorial_events WHERE resource_id=? ORDER BY created_at,id",id));return row;}
 public List<Map<String,Object>> workspace(UUID actor,int page){actor(actor);if(page<0||page>100000)throw new IllegalArgumentException("Invalid editorial page");var ids=db.queryForList("SELECT r.id FROM growth_resources r JOIN growth_resource_versions v ON v.resource_id=r.id AND v.revision=r.current_revision WHERE r.author_id=? OR (v.state='SUBMITTED' AND educational_permission_live(?,'REVIEW',v.document->>'scope')) ORDER BY r.created_at DESC,r.id DESC LIMIT 30 OFFSET ?",UUID.class,actor,actor,(long)page*30);return ids.stream().map(id->editorial(actor,id)).toList();}
 public Map<String,Object> detail(UUID actor,UUID id){actor(actor);if(!truth("SELECT growth_resource_available(?)",id))throw new NotFoundException("Reviewed resource is unavailable");int revision=db.queryForObject("SELECT published_revision FROM growth_resources WHERE id=?",Integer.class,id);var row=version(id,revision);var result=new LinkedHashMap<String,Object>();result.put("id",id);result.put("revision",revision);result.put("document",row.get("document"));result.put("reviewedAt",row.get("reviewed_at"));result.put("publishedAt",row.get("published_at"));result.put("reviewNote",row.get("review_note"));result.put("author",db.queryForObject("SELECT display_name FROM profiles WHERE user_id=?",String.class,row.get("author_id")));result.put("reviewer",db.queryForObject("SELECT display_name FROM profiles WHERE user_id=?",String.class,row.get("reviewer_id")));result.put("scope",scope(row));result.put("saved",truth("SELECT EXISTS(SELECT 1 FROM growth_resource_saves WHERE user_id=? AND resource_id=?) OR EXISTS(SELECT 1 FROM article_saves WHERE user_id=? AND article_id=?) OR EXISTS(SELECT 1 FROM media_saves WHERE user_id=? AND media_id=?)",actor,id,actor,row.get("legacy_article_id"),actor,row.get("legacy_media_id")));return result;}
 public Map<String,Object> browse(UUID actor,String search,String kind,String topic,String language,boolean saved,int page){actor(actor);if(saved)return saved(actor,search,kind,topic,language,page);if(page<0||page>100000)throw new IllegalArgumentException("Invalid library page");String q=text(search,160,false),type=text(kind,30,false),tag=text(topic,80,false),lang=text(language,10,false);var ids=db.queryForList("SELECT r.id FROM growth_resources r JOIN growth_resource_versions v ON v.resource_id=r.id AND v.revision=r.published_revision WHERE growth_resource_available(r.id) AND (position(lower(?) in lower(v.document->>'title'))>0 OR position(lower(?) in lower(v.document->>'summary'))>0) AND(?='' OR v.document->>'kind'=?) AND(?='' OR v.document->>'topic'=?) AND(?='' OR v.document->>'language'=?) AND(NOT ? OR EXISTS(SELECT 1 FROM growth_resource_saves s WHERE s.user_id=? AND s.resource_id=r.id) OR EXISTS(SELECT 1 FROM article_saves s WHERE s.user_id=? AND s.article_id=r.legacy_article_id) OR EXISTS(SELECT 1 FROM media_saves s WHERE s.user_id=? AND s.media_id=r.legacy_media_id)) ORDER BY r.featured DESC,r.created_at DESC,r.id DESC LIMIT 21 OFFSET ?",UUID.class,q,q,type,type,tag,tag,lang,lang,saved,actor,actor,actor,(long)page*20);return Map.of("items",ids.stream().limit(20).map(id->detail(actor,id)).toList(),"hasMore",ids.size()>20);}
 private Map<String,Object> saved(UUID actor,String search,String kind,String topic,String language,int page){if(page<0||page>100000)throw new IllegalArgumentException("Invalid library page");String q=text(search,160,false),type=text(kind,30,false),tag=text(topic,80,false),lang=text(language,10,false);var ids=db.queryForList("SELECT r.id FROM growth_resources r JOIN growth_resource_versions v ON v.resource_id=r.id AND v.revision=COALESCE(r.published_revision,r.current_revision) WHERE(EXISTS(SELECT 1 FROM growth_resource_saves s WHERE s.user_id=? AND s.resource_id=r.id) OR EXISTS(SELECT 1 FROM article_saves s WHERE s.user_id=? AND s.article_id=r.legacy_article_id) OR EXISTS(SELECT 1 FROM media_saves s WHERE s.user_id=? AND s.media_id=r.legacy_media_id)) AND(position(lower(?) in lower(v.document->>'title'))>0 OR position(lower(?) in lower(v.document->>'summary'))>0) AND(?='' OR v.document->>'kind'=?) AND(?='' OR v.document->>'topic'=?) AND(?='' OR v.document->>'language'=?) ORDER BY r.created_at DESC,r.id DESC LIMIT 21 OFFSET ?",UUID.class,actor,actor,actor,q,q,type,type,tag,tag,lang,lang,(long)page*20);return Map.of("items",ids.stream().limit(20).map(id->truth("SELECT growth_resource_available(?)",id)?detail(actor,id):Map.<String,Object>of("id",id,"revision",0,"available",false,"saved",true,"document",Map.of("kind","UNAVAILABLE","title","Resource unavailable / منبع ناموجود","summary","","language","","warnings",List.of()))).toList(),"hasMore",ids.size()>20);}
 public void save(UUID actor,UUID id,boolean saved){
  actor(actor);if(saved)detail(actor,id);
  var rows=db.queryForList("SELECT legacy_article_id,legacy_media_id FROM growth_resources WHERE id=?",id);
  if(rows.isEmpty()){if(saved)throw new NotFoundException("Resource was not found");return;}
  var row=rows.getFirst();
  if(row.get("legacy_article_id")!=null){
   if(saved)db.update("INSERT INTO article_saves(user_id,article_id) VALUES (?,?) ON CONFLICT DO NOTHING",actor,row.get("legacy_article_id"));
   else db.update("DELETE FROM article_saves WHERE user_id=? AND article_id=?",actor,row.get("legacy_article_id"));
  }else if(row.get("legacy_media_id")!=null){
   if(saved)db.update("INSERT INTO media_saves(user_id,media_id) VALUES (?,?) ON CONFLICT DO NOTHING",actor,row.get("legacy_media_id"));
   else db.update("DELETE FROM media_saves WHERE user_id=? AND media_id=?",actor,row.get("legacy_media_id"));
  }else if(saved)db.update("INSERT INTO growth_resource_saves(user_id,resource_id) VALUES (?,?) ON CONFLICT DO NOTHING",actor,id);
  else db.update("DELETE FROM growth_resource_saves WHERE user_id=? AND resource_id=?",actor,id);
 }
 private void expiry(Instant at){if(at==null||at.isBefore(Instant.now().plusSeconds(60))||at.isAfter(Instant.now().plus(Duration.ofDays(366))))throw new IllegalArgumentException("Choose a bounded future expiry within one year");}
 public UUID grant(UUID actor,Grant in){admin(actor);actor(in.userId());if(actor.equals(in.userId()))throw new ForbiddenException("Permissions require an independent issuer");if(!Set.of("DRAFT","SUBMIT","REVIEW","APPROVE","PUBLISH","FEATURE","RETIRE","ATTACH").contains(in.action()))throw new IllegalArgumentException("Unknown permission");String scope=text(in.scope(),80,true);if(!scope.equals("GENERAL")&&!truth("SELECT educational_credential_live(?,?)",in.userId(),scope))throw new ForbiddenException("Verify the independent scope first");if(Set.of("REVIEW","APPROVE","PUBLISH","FEATURE","RETIRE").contains(in.action()))staff(in.userId());expiry(in.expiresAt());return db.queryForObject("INSERT INTO educational_permissions(user_id,action,scope,issued_by,evidence,expires_at) VALUES (?,?,?,?,?,?) RETURNING id",UUID.class,in.userId(),in.action(),scope,actor,text(in.evidence(),2000,true),in.expiresAt().atOffset(ZoneOffset.UTC));}
 public UUID credential(UUID actor,Credential in){admin(actor);if(actor.equals(in.userId()))throw new ForbiddenException("Independent verification is required");if(!truth("SELECT EXISTS(SELECT 1 FROM professional_verifications v JOIN professional_profiles p ON p.user_id=v.professional_user_id WHERE v.id=? AND v.professional_user_id=? AND v.status='APPROVED' AND v.reviewed_by<>v.professional_user_id AND v.reviewed_at IS NOT NULL AND p.verification_status='VERIFIED' AND EXISTS(SELECT 1 FROM professional_application_documents d WHERE d.application_id=v.id AND d.scan_status='CLEAN' AND d.scanned_at IS NOT NULL AND d.reviewed_by<>v.professional_user_id))",in.verificationId(),in.userId()))throw new ForbiddenException("An independently approved application and reviewed clean document are required");expiry(in.expiresAt());return db.queryForObject("INSERT INTO educational_credentials(user_id,verification_id,scope,verified_by,reference,expires_at) VALUES (?,?,?,?,?,?) RETURNING id",UUID.class,in.userId(),in.verificationId(),text(in.scope(),80,true),actor,text(in.reference(),2000,true),in.expiresAt().atOffset(ZoneOffset.UTC));}
 public List<Map<String,Object>> grants(UUID actor,int page){admin(actor);if(page<0||page>100000)throw new IllegalArgumentException("Invalid permission page");return db.queryForList("SELECT id,user_id,action,scope,evidence,expires_at,revoked_at FROM educational_permissions ORDER BY created_at DESC,id LIMIT 50 OFFSET ?",(long)page*50);}
 public void revoke(UUID actor,UUID id,boolean credential){admin(actor);db.update("UPDATE "+(credential?"educational_credentials":"educational_permissions")+" SET revoked_at=CURRENT_TIMESTAMP WHERE id=?",id);}
 private void post(UUID actor,UUID id){actor(actor);posts.get(id,actor);}
 private void postLock(UUID id){var rows=db.queryForList("SELECT community_id FROM posts WHERE id=?",id);if(!rows.isEmpty()&&rows.getFirst().get("community_id")!=null)db.queryForList("SELECT id FROM communities WHERE id=? FOR UPDATE",rows.getFirst().get("community_id"));db.queryForList("SELECT id FROM posts WHERE id=? FOR UPDATE",id);}
 public Map<String,Object> preference(UUID actor,UUID post){post(actor,post);boolean owned=truth("SELECT EXISTS(SELECT 1 FROM posts WHERE id=? AND author_id=?)",post,actor);var rows=db.queryForList("SELECT allowed,revision FROM post_resource_preferences WHERE post_id=?",post);var result=new LinkedHashMap<String,Object>();result.put("owned",owned);result.put("allowed",!rows.isEmpty()&&Boolean.TRUE.equals(rows.getFirst().get("allowed")));if(owned)result.put("revision",rows.isEmpty()?0:rows.getFirst().get("revision"));return result;}
 public Map<String,Object> preference(UUID actor,UUID post,Preference in){postLock(post);post(actor,post);if(!truth("SELECT EXISTS(SELECT 1 FROM posts WHERE id=? AND author_id=?)",post,actor))throw new NotFoundException("Own post was not found");db.update("INSERT INTO post_resource_preferences(post_id) VALUES (?) ON CONFLICT DO NOTHING",post);if(db.update("UPDATE post_resource_preferences SET allowed=?,revision=revision+1 WHERE post_id=? AND revision=?",in.allowed(),post,in.revision())!=1)throw new ConflictException("Attachment preference changed. Reload first.");db.update("UPDATE post_resource_attachments SET status='REMOVED' WHERE post_id=? AND status IN('PROPOSED','APPROVED')",post);return preference(actor,post);}
 public Map<String,Object> propose(UUID actor,UUID post,Proposal in){postLock(post);post(actor,post);if(!truth("SELECT EXISTS(SELECT 1 FROM posts WHERE id=? AND status='PUBLISHED')",post))throw new ConflictException("Resources may be proposed only on an accessible published post");var resource=detail(actor,in.resourceId());permission(actor,"ATTACH",(String)resource.get("scope"));if(!truth("SELECT EXISTS(SELECT 1 FROM post_resource_preferences WHERE post_id=? AND allowed)",post))throw new ForbiddenException("The original author has not allowed educational resources");if(!truth("SELECT count(*)<8 FROM post_resource_attachments WHERE post_id=? AND status IN('PROPOSED','APPROVED')",post))throw new IllegalArgumentException("Attachment limit reached");UUID id=db.queryForObject("INSERT INTO post_resource_attachments(post_id,resource_id,resource_revision,post_revision,preference_revision,proposed_by,reason) SELECT p.id,?,?,p.revision,pref.revision,?,? FROM posts p JOIN post_resource_preferences pref ON pref.post_id=p.id WHERE p.id=? ON CONFLICT(post_id,resource_id) DO UPDATE SET status='PROPOSED',resource_revision=EXCLUDED.resource_revision,post_revision=EXCLUDED.post_revision,preference_revision=EXCLUDED.preference_revision,proposed_by=EXCLUDED.proposed_by,reviewed_by=NULL,reviewed_at=NULL,reason=EXCLUDED.reason RETURNING id",UUID.class,in.resourceId(),resource.get("revision"),actor,text(in.reason(),1000,true),post);return Map.of("id",id,"status","PROPOSED");}
 public void reviewAttachment(UUID actor,UUID post,UUID attachment,String note){postLock(post);post(actor,post);staff(actor);var rows=db.queryForList("SELECT a.*,v.document->>'scope' AS scope FROM post_resource_attachments a JOIN growth_resources r ON r.id=a.resource_id JOIN growth_resource_versions v ON v.resource_id=r.id AND v.revision=r.published_revision WHERE a.id=? AND a.post_id=? FOR UPDATE OF a",attachment,post);if(rows.isEmpty())throw new NotFoundException("Attachment was not found");var row=rows.getFirst();permission(actor,"REVIEW",(String)row.get("scope"));permission(actor,"APPROVE",(String)row.get("scope"));if(actor.equals(row.get("proposed_by")))throw new ForbiddenException("Independent attachment review is required");detail(actor,(UUID)row.get("resource_id"));if(!truth("SELECT EXISTS(SELECT 1 FROM post_resource_attachments a JOIN posts p ON p.id=a.post_id JOIN post_resource_preferences pref ON pref.post_id=p.id JOIN growth_resources r ON r.id=a.resource_id WHERE a.id=? AND a.status='PROPOSED' AND pref.allowed AND pref.revision=a.preference_revision AND p.revision=a.post_revision AND r.published_revision=a.resource_revision)",attachment))throw new ConflictException("The author preference, post or resource changed");db.update("UPDATE post_resource_attachments SET status='APPROVED',reviewed_by=?,review_note=?,reviewed_at=CURRENT_TIMESTAMP WHERE id=?",actor,text(note,1000,true),attachment);}
 public List<Map<String,Object>> attachments(UUID actor,UUID post){post(actor,post);var rows=db.queryForList("SELECT a.id,a.resource_id FROM post_resource_attachments a JOIN posts p ON p.id=a.post_id JOIN post_resource_preferences pref ON pref.post_id=p.id JOIN growth_resources r ON r.id=a.resource_id WHERE a.post_id=? AND p.status='PUBLISHED' AND a.status='APPROVED' AND pref.allowed AND pref.revision=a.preference_revision AND p.revision=a.post_revision AND r.published_revision=a.resource_revision AND growth_resource_available(r.id) ORDER BY a.created_at,a.id LIMIT 8",post);return rows.stream().map(row->Map.<String,Object>of("id",row.get("id"),"resource",detail(actor,(UUID)row.get("resource_id")))).toList();}
 public List<Map<String,Object>> proposals(UUID actor,UUID post){post(actor,post);staff(actor);var rows=db.queryForList("SELECT a.id,a.resource_id,a.reason,a.status,a.resource_revision FROM post_resource_attachments a JOIN growth_resource_versions v ON v.resource_id=a.resource_id AND v.revision=a.resource_revision WHERE a.post_id=? AND educational_permission_live(?,'REVIEW',v.document->>'scope') ORDER BY a.created_at LIMIT 30",post,actor);return rows;}
 public void removeAttachment(UUID actor,UUID post,UUID attachment){postLock(post);post(actor,post);if(!truth("SELECT EXISTS(SELECT 1 FROM posts WHERE id=? AND author_id=?)",post,actor))throw new ForbiddenException("Only the original author can remove this association");db.update("UPDATE post_resource_attachments SET status='REMOVED' WHERE id=? AND post_id=?",attachment,post);}
}
